// Game audio. The narrator, sound effects, ambience beds and the score are ElevenLabs
// recordings in public/audio (generated by pipeline/eleven.mjs, listed in sound-jobs.mjs).
// Everything is mixed through Web Audio: a voice bus that ducks the music and ambience, per-file
// loudness normalisation measured at decode time, stereo panning for world sounds, and
// crossfading music and ambience loops. The original procedural synth is kept as the fallback,
// so any sound whose file is missing (or still loading) is synthesised instead of going silent.

type Mood = 'silent' | 'calm' | 'wonder' | 'tense' | 'triumph';
export type VoiceMode = 'queue' | 'drop' | 'interrupt';

const SCALE = [0, 2, 3, 7, 9, 10, 12, 14, 15, 19]; // D dorian-ish pentatonic flavour
const ROOT = 50; // D3
const AUDIO_BASE = `${import.meta.env.BASE_URL}audio/`;

function mtof(m: number) {
  return 440 * Math.pow(2, (m - 69) / 12);
}

/** Game sound name -> recorded files (one picked at random) and a mix level. */
const CUES: Record<string, { ids: string[]; vol: number; vary?: number }> = {
  jump: { ids: ['sfx_jump'], vol: 0.45, vary: 0.08 },
  flip: { ids: ['sfx_flip'], vol: 0.55, vary: 0.06 },
  walljump: { ids: ['sfx_walljump'], vol: 0.6, vary: 0.08 },
  hardLand: { ids: ['sfx_hardland'], vol: 0.75 },
  pound: { ids: ['sfx_pound_fall'], vol: 0.6 },
  poundImpact: { ids: ['sfx_pound_impact'], vol: 1 },
  climb: { ids: ['sfx_climb'], vol: 0.5, vary: 0.08 },
  imprint: { ids: ['sfx_imprint'], vol: 0.8 },
  crumble: { ids: ['sfx_crumble'], vol: 0.9 },
  splash: { ids: ['sfx_splash'], vol: 0.7, vary: 0.06 },
  bubbles: { ids: ['sfx_bubbles'], vol: 0.5 },
  checkpoint: { ids: ['sfx_checkpoint'], vol: 0.55 },
  plateDown: { ids: ['sfx_plate_down'], vol: 0.75 },
  plateUp: { ids: ['sfx_plate_up'], vol: 0.5 },
  gate: { ids: ['sfx_gate'], vol: 0.8 },
  thud: { ids: ['sfx_thud'], vol: 0.7, vary: 0.05 },
  melt: { ids: ['sfx_melt'], vol: 0.8 },
  burn: { ids: ['sfx_burn'], vol: 0.8 },
  shatter: { ids: ['sfx_shatter'], vol: 0.85 },
  respawn: { ids: ['sfx_respawn'], vol: 0.55 },
  rumble: { ids: ['sfx_rumble'], vol: 0.9 },
  slam: { ids: ['sfx_slam'], vol: 1 },
  awaken: { ids: ['sfx_awaken'], vol: 0.7 },
  absorb: { ids: ['sfx_absorb'], vol: 0.75 },
  restore: { ids: ['sfx_restore'], vol: 0.75 },
  sting: { ids: ['mus_restore_sting'], vol: 0.55 },
  titleBoom: { ids: ['sfx_title_boom'], vol: 0.7 },
  roar: { ids: ['sfx_colossus_roar'], vol: 1 },
  colossusStep: { ids: ['sfx_colossus_step'], vol: 0.6, vary: 0.05 },
  ui: { ids: ['sfx_ui_confirm'], vol: 0.45 },
  uiMove: { ids: ['sfx_ui_move'], vol: 0.35 },
  uiBack: { ids: ['sfx_ui_back'], vol: 0.4 },
  loamWake: { ids: ['vx_loam_wake'], vol: 0.6 },
  loamHup: { ids: ['vx_loam_hup'], vol: 0.45, vary: 0.06 },
  loamOof: { ids: ['vx_loam_oof'], vol: 0.5, vary: 0.05 },
  loamHurt: { ids: ['vx_loam_hurt'], vol: 0.55 },
  loamYay: { ids: ['vx_loam_yay'], vol: 0.55 },
};
const FORM_CUES: Record<string, { prefix: string; vol: number; vary: number }> = {
  step: { prefix: 'sfx_step_', vol: 0.28, vary: 0.1 },
  land: { prefix: 'sfx_land_', vol: 0.55, vary: 0.06 },
  transform: { prefix: 'sfx_tf_', vol: 0.7, vary: 0 },
};
const FORMS = ['clay', 'stone', 'wood', 'glass'];
const VOICE_IDS = [
  'vo_intro_1', 'vo_intro_2', 'vo_intro_3', 'vo_title', 'vo_h_move', 'vo_h_balcony', 'vo_h_pound', 'vo_h_push', 'vo_h_charge',
  'vo_h_climb', 'vo_h_water', 'vo_h_sink', 'vo_h_float', 'vo_h_fire', 'vo_h_glass', 'vo_altar_stone', 'vo_altar_wood',
  'vo_altar_glass', 'vo_form_stone', 'vo_form_wood', 'vo_form_glass', 'vo_colossus', 'vo_run', 'vo_esc_1', 'vo_esc_2',
  'vo_d_shatter', 'vo_d_melt', 'vo_d_burn', 'vo_finale_1', 'vo_finale_2', 'vo_thanks', 'vo_h_push2', 'vo_h_glass2', 'vo_h_woodgate', 'vo_trial', 'vo_h_prism1', 'vo_h_prism2', 'vo_h_well',
];
export type AmbienceId = 'amb_hall' | 'amb_water' | 'amb_fire' | 'amb_valley' | 'amb_collapse';
const AMBIENCE: AmbienceId[] = ['amb_hall', 'amb_water', 'amb_fire', 'amb_valley', 'amb_collapse'];
const MUSIC: Record<Exclude<Mood, 'silent'> | 'title', { id: string; level: number }> = {
  calm: { id: 'mus_explore', level: 0.5 },
  wonder: { id: 'mus_explore', level: 0.62 },
  tense: { id: 'mus_escape', level: 0.75 },
  triumph: { id: 'mus_finale', level: 0.8 },
  title: { id: 'mus_title', level: 0.7 },
};

/** Loudness of the loudest 100 ms of a buffer (RMS), used to even out the generated files. */
export function peakWindowRms(buf: AudioBuffer) {
  const win = Math.max(1, Math.floor(buf.sampleRate * 0.1));
  let best = 0;
  for (let c = 0; c < buf.numberOfChannels; c++) {
    const d = buf.getChannelData(c);
    for (let i = 0; i + win <= d.length; i += win) {
      let s = 0;
      for (let j = i; j < i + win; j += 2) s += d[j] * d[j];
      best = Math.max(best, s / (win / 2));
    }
  }
  return Math.sqrt(best);
}

interface Sample {
  buf: AudioBuffer;
  norm: number;
}
/** Receives the sound the game would play (dev trailer capture renders it offline in sync). */
export interface AudioTap {
  sfx(id: string, vol: number, rate: number, pan: number): void;
  voice(id: string, mode: VoiceMode): void;
  music(id: string | null, level: number, fade: number): void;
  amb(levels: Partial<Record<AmbienceId, number>>): void;
}
interface Bed {
  src: AudioBufferSourceNode;
  gain: GainNode;
  level: number;
}
interface Track {
  el: HTMLAudioElement;
  gain: GainNode;
  broken: boolean;
  stopTimer: number;
}

export class Audio {
  ctx: AudioContext | null = null;
  private master!: GainNode;
  private music!: GainNode;
  private sfxBus!: GainNode;
  private voiceBus!: GainNode;
  private ambBus!: GainNode;
  private trackBus!: GainNode;
  private reverb!: ConvolverNode;
  private reverbSend!: GainNode;
  private noiseBuf!: AudioBuffer;
  private mood: Mood = 'silent';
  private nextNote = 0;
  private nextChord = 0;
  private chordIdx = 0;
  private padVoices: { osc: OscillatorNode[]; gain: GainNode; filter: BiquadFilterNode }[] = [];
  private drone: { osc: OscillatorNode; gain: GainNode } | null = null;
  private pulseNext = 0;
  muted = false;
  /** Never create an AudioContext at all. Dev builds default to this so tests and captures stay silent. */
  silent = false;
  /** When set, sounds are reported here instead of played (trailer capture). */
  recorder: AudioTap | null = null;
  /** True while a cutscene is being skipped: its narration and effects are not played at all. */
  hushed = false;

  private samples = new Map<string, Sample>();
  private loading: Promise<void> | null = null;
  private beds = new Map<AmbienceId, Bed>();
  private bedTargets: Partial<Record<AmbienceId, number>> = {};
  private tracks = new Map<string, Track>();
  private trackWanted: { id: string; level: number } | null = null;
  private trackPlaying: string | null = null;
  private trackFailed = new Set<string>();
  private voiceSrc: AudioBufferSourceNode | null = null;
  private voiceEndsAt = 0;
  private voiceQueue: string[] = [];
  private duck = 1;
  /** Seconds of narration still to come (cutscenes can wait for a line to finish). */
  get voiceRemaining() {
    return this.ctx ? Math.max(0, this.voiceEndsAt - this.ctx.currentTime) + this.voiceQueue.reduce((s, id) => s + (this.samples.get(id)?.buf.duration ?? 0) + 0.2, 0) : 0;
  }

  /** Fetch and decode the narration and effects early (before the first click) so the intro is voiced from its first line. */
  preload() {
    if (this.silent || this.loading) return this.loading ?? Promise.resolve();
    const decoder = typeof OfflineAudioContext !== 'undefined' ? new OfflineAudioContext(2, 1, 44100) : null;
    if (!decoder) return Promise.resolve();
    const ids = [
      ...VOICE_IDS.slice(0, 5),
      'sfx_ui_confirm', 'sfx_awaken', 'vx_loam_wake', 'sfx_title_boom', 'sfx_step_clay', 'sfx_jump', 'sfx_land_clay', 'sfx_flip', 'amb_hall',
      'sfx_dash', 'sfx_charge',
      ...Object.values(CUES).flatMap((c) => c.ids),
      ...Object.values(FORM_CUES).flatMap((c) => FORMS.map((f) => c.prefix + f)),
      ...VOICE_IDS,
      ...AMBIENCE,
    ];
    const queue = [...new Set(ids)];
    const load = async (id: string) => {
      try {
        const r = await fetch(`${AUDIO_BASE}${id}.mp3`);
        if (!r.ok) return;
        const buf = await decoder.decodeAudioData(await r.arrayBuffer());
        const rms = peakWindowRms(buf);
        const target = id.startsWith('vo_') ? 0.17 : id.startsWith('amb_') || id.startsWith('mus_') ? 0.14 : 0.2;
        this.samples.set(id, { buf, norm: rms > 1e-4 ? Math.min(3, Math.max(0.25, target / rms)) : 1 });
      } catch {
        // missing or undecodable: the procedural synth covers this sound
      }
    };
    const worker = async () => {
      for (let id = queue.shift(); id; id = queue.shift()) await load(id);
    };
    this.loading = Promise.all(Array.from({ length: 6 }, worker)).then(() => {});
    return this.loading;
  }

  /** Must be called from a user gesture. */
  start() {
    if (this.silent) return;
    if (this.ctx) {
      void this.ctx.resume();
      return;
    }
    void this.preload();
    const ctx = new AudioContext();
    this.ctx = ctx;
    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.9;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -14;
    comp.ratio.value = 3;
    comp.attack.value = 0.005;
    comp.release.value = 0.2;
    // a safety limiter so stacked impacts and narration never clip the output
    const limiter = ctx.createDynamicsCompressor();
    limiter.threshold.value = -2;
    limiter.knee.value = 0;
    limiter.ratio.value = 20;
    limiter.attack.value = 0.001;
    limiter.release.value = 0.12;
    this.master.connect(comp).connect(limiter).connect(ctx.destination);
    this.music = ctx.createGain();
    this.music.gain.value = 0.0;
    this.sfxBus = ctx.createGain();
    this.sfxBus.gain.value = 0.85;
    this.voiceBus = ctx.createGain();
    this.voiceBus.gain.value = 1.0;
    this.ambBus = ctx.createGain();
    this.ambBus.gain.value = 0.5;
    this.trackBus = ctx.createGain();
    this.trackBus.gain.value = 0.42;
    this.reverb = ctx.createConvolver();
    this.reverb.buffer = this.impulse(3.8, 2.6);
    this.reverbSend = ctx.createGain();
    this.reverbSend.gain.value = 0.55;
    this.music.connect(this.master);
    this.music.connect(this.reverbSend);
    this.sfxBus.connect(this.master);
    this.voiceBus.connect(this.master);
    this.ambBus.connect(this.master);
    this.trackBus.connect(this.master);
    const sfxSend = ctx.createGain();
    sfxSend.gain.value = 0.18;
    this.sfxBus.connect(sfxSend).connect(this.reverb);
    const voiceSend = ctx.createGain();
    voiceSend.gain.value = 0.06; // a touch of the hall on the narrator
    this.voiceBus.connect(voiceSend).connect(this.reverb);
    this.reverbSend.connect(this.reverb);
    this.reverb.connect(this.master);
    this.noiseBuf = ctx.createBuffer(1, ctx.sampleRate * 2, ctx.sampleRate);
    const d = this.noiseBuf.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    // drone (procedural score fallback)
    const o = ctx.createOscillator();
    o.type = 'sine';
    o.frequency.value = mtof(ROOT - 12);
    const g = ctx.createGain();
    g.gain.value = 0;
    o.connect(g).connect(this.music);
    o.start();
    this.drone = { osc: o, gain: g };
    this.nextNote = ctx.currentTime + 1;
    this.nextChord = ctx.currentTime + 0.2;
  }

  private impulse(seconds: number, decay: number) {
    const ctx = this.ctx!;
    const len = Math.floor(ctx.sampleRate * seconds);
    const buf = ctx.createBuffer(2, len, ctx.sampleRate);
    for (let c = 0; c < 2; c++) {
      const ch = buf.getChannelData(c);
      for (let i = 0; i < len; i++) ch[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, decay);
    }
    return buf;
  }

  // ------------------------------------------------------------------ music
  setMood(m: Mood, fade = 2.5) {
    this.recorder?.music(m === 'silent' ? null : MUSIC[m].id, m === 'silent' ? 0 : MUSIC[m].level, fade);
    this.mood = m;
    if (m === 'silent') this.wantTrack(null, fade);
    else this.wantTrack(MUSIC[m], fade);
    if (!this.ctx) return;
    this.applyProceduralLevel(fade);
    this.nextChord = this.ctx.currentTime + 0.05;
  }

  /** Title-screen extras (the Maker's Archive) get the title theme. */
  titleMusic(on: boolean) {
    this.recorder?.music(on ? MUSIC.title.id : null, on ? MUSIC.title.level : 0, 1.5);
    this.wantTrack(on ? MUSIC.title : null, 1.5);
  }

  private wantTrack(t: { id: string; level: number } | null, fade: number) {
    this.trackWanted = t;
    if (!this.ctx) return;
    const ctx = this.ctx;
    for (const [id, tr] of this.tracks) {
      if (t && id === t.id) continue;
      tr.gain.gain.cancelScheduledValues(ctx.currentTime);
      tr.gain.gain.setTargetAtTime(0, ctx.currentTime, Math.max(0.05, fade / 3));
      window.clearTimeout(tr.stopTimer);
      tr.stopTimer = window.setTimeout(() => tr.el.pause(), fade * 1000 + 600);
    }
    this.trackPlaying = null;
    if (!t) return;
    const tr = this.track(t.id);
    if (!tr || tr.broken) return;
    window.clearTimeout(tr.stopTimer);
    tr.gain.gain.cancelScheduledValues(ctx.currentTime);
    tr.gain.gain.setTargetAtTime(t.level, ctx.currentTime, Math.max(0.05, fade / 3));
    if (tr.el.paused) void tr.el.play().catch(() => (tr.broken = true));
    this.trackPlaying = t.id;
  }

  private track(id: string): Track | null {
    const ctx = this.ctx;
    if (!ctx) return null;
    let tr = this.tracks.get(id);
    if (tr) return tr;
    const el = document.createElement('audio');
    el.src = `${AUDIO_BASE}${id}.mp3`;
    el.loop = true;
    el.preload = 'auto';
    const gain = ctx.createGain();
    gain.gain.value = 0;
    try {
      ctx.createMediaElementSource(el).connect(gain).connect(this.trackBus);
    } catch {
      return null;
    }
    tr = { el, gain, broken: false, stopTimer: 0 };
    const t = tr;
    el.addEventListener('error', () => {
      t.broken = true;
      this.applyProceduralLevel(2);
    });
    this.tracks.set(id, tr);
    return tr;
  }

  /** The procedural score only plays when the recorded track for this mood is unavailable. */
  private applyProceduralLevel(fade: number) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const m = this.mood;
    const recorded = this.trackPlaying && !this.tracks.get(this.trackPlaying)?.broken;
    const level = recorded || m === 'silent' ? 0 : m === 'tense' ? 0.55 : m === 'triumph' ? 0.6 : 0.45;
    this.music.gain.cancelScheduledValues(t);
    this.music.gain.setTargetAtTime(this.muted ? 0 : level, t, fade / 3);
    if (this.drone) this.drone.gain.gain.setTargetAtTime(recorded ? 0 : m === 'tense' ? 0.22 : m === 'silent' ? 0 : 0.12, t, fade / 3);
  }

  toggleMute() {
    this.muted = !this.muted;
    if (this.ctx) this.master.gain.setTargetAtTime(this.muted ? 0 : 0.9, this.ctx.currentTime, 0.1);
    return this.muted;
  }

  private pauseTimer = 0;
  /** The pause menu: every sound holds where it is (a paused cutscene's narration stays in step). */
  setPaused(on: boolean) {
    const ctx = this.ctx;
    if (!ctx) return;
    clearTimeout(this.pauseTimer);
    // a moment's grace so the menu's own click is heard
    if (on) this.pauseTimer = window.setTimeout(() => void ctx.suspend().catch(() => {}), 160);
    else void ctx.resume().catch(() => {});
  }

  // ------------------------------------------------------------------ ambience
  /** Target levels (0..1) for the looping ambience beds; anything not listed fades out. */
  setAmbience(levels: Partial<Record<AmbienceId, number>>) {
    this.recorder?.amb(levels);
    this.bedTargets = levels;
  }

  private updateBeds() {
    const ctx = this.ctx!;
    for (const id of AMBIENCE) {
      const want = this.bedTargets[id] ?? 0;
      let bed = this.beds.get(id);
      if (!bed && want > 0.01) {
        const s = this.samples.get(id);
        if (!s) continue;
        const src = ctx.createBufferSource();
        src.buffer = s.buf;
        src.loop = true;
        src.loopStart = Math.min(0.05, s.buf.duration * 0.1);
        src.loopEnd = Math.max(src.loopStart + 0.1, s.buf.duration - 0.05);
        const gain = ctx.createGain();
        gain.gain.value = 0;
        src.connect(gain).connect(this.ambBus);
        src.start(ctx.currentTime, Math.random() * s.buf.duration * 0.8);
        bed = { src, gain, level: 0 };
        this.beds.set(id, bed);
      }
      if (!bed) continue;
      const norm = this.samples.get(id)?.norm ?? 1;
      if (Math.abs(bed.level - want) > 0.005) {
        bed.level = want;
        bed.gain.gain.setTargetAtTime(want * norm, ctx.currentTime, 0.8);
      }
    }
  }

  // ------------------------------------------------------------------ narration
  /** Speak a narrator line. 'queue' waits for the current line, 'drop' skips if one is playing. */
  say(id: string, mode: VoiceMode = 'queue') {
    if (this.hushed) return 0;
    if (this.recorder) {
      this.recorder.voice(id, mode);
      return 1;
    }
    const ctx = this.ctx;
    if (!ctx || this.muted) return 0;
    const s = this.samples.get(id);
    if (!s) return 0;
    const busy = ctx.currentTime < this.voiceEndsAt - 0.05;
    if (busy && mode === 'drop') return 0;
    if (busy && mode === 'queue') {
      this.voiceQueue.push(id);
      return s.buf.duration;
    }
    if (busy && mode === 'interrupt') {
      this.voiceQueue = [];
      try {
        this.voiceSrc?.stop();
      } catch {
        /* already stopped */
      }
    }
    this.speakNow(id);
    return s.buf.duration;
  }

  /** Stop the narrator now and forget anything queued (a skipped cutscene). */
  stopVoice() {
    this.voiceQueue = [];
    if (this.voiceSrc) {
      try {
        this.voiceSrc.stop();
      } catch {
        /* already finished */
      }
      this.voiceSrc = null;
    }
    if (this.ctx) this.voiceEndsAt = this.ctx.currentTime;
  }

  private speakNow(id: string) {
    const ctx = this.ctx!;
    const s = this.samples.get(id);
    if (!s) return;
    const src = ctx.createBufferSource();
    src.buffer = s.buf;
    const g = ctx.createGain();
    g.gain.value = s.norm;
    src.connect(g).connect(this.voiceBus);
    const at = ctx.currentTime + 0.02;
    src.start(at);
    this.voiceSrc = src;
    this.voiceEndsAt = at + s.buf.duration;
  }

  /** Called every frame: schedules notes a little ahead of time, runs the narration queue, ducking and ambience. */
  update() {
    const ctx = this.ctx;
    if (!ctx) return;
    const t = ctx.currentTime;
    // narration queue and ducking of music and ambience under the voice
    if (this.voiceQueue.length && t >= this.voiceEndsAt + 0.2) this.speakNow(this.voiceQueue.shift()!);
    const talking = t < this.voiceEndsAt;
    const duck = talking ? 0.45 : 1;
    if (duck !== this.duck) {
      this.duck = duck;
      this.trackBus.gain.setTargetAtTime(0.42 * duck, t, talking ? 0.12 : 0.6);
      this.ambBus.gain.setTargetAtTime(0.5 * (talking ? 0.6 : 1), t, talking ? 0.12 : 0.6);
    }
    // a wanted track that could not start yet (audio was still locked) starts now
    const w = this.trackWanted;
    if (w && this.trackPlaying !== w.id && !this.tracks.get(w.id)?.broken && !this.trackFailed.has(w.id)) {
      this.wantTrack(w, 2);
      if (this.trackPlaying !== w.id) this.trackFailed.add(w.id);
    }
    this.updateBeds();
    if (this.mood === 'silent' || (this.trackPlaying && !this.tracks.get(this.trackPlaying)?.broken)) return;
    const progressions: Record<Exclude<Mood, 'silent'>, number[][]> = {
      calm: [[0, 7, 10, 14], [-2, 5, 9, 14], [3, 7, 10, 15], [-4, 3, 7, 12]],
      wonder: [[0, 7, 9, 16], [5, 9, 12, 16], [-3, 4, 9, 12], [2, 9, 14, 17]],
      tense: [[0, 3, 7, 10], [-1, 3, 6, 10], [0, 3, 7, 12], [-2, 2, 5, 10]],
      triumph: [[0, 4, 7, 12], [5, 9, 12, 16], [7, 11, 14, 19], [0, 4, 7, 16]],
    };
    const mood = this.mood as Exclude<Mood, 'silent'>;
    const chordLen = mood === 'tense' ? 3.2 : mood === 'triumph' ? 4 : 6;
    if (t + 0.2 >= this.nextChord) {
      const chord = progressions[mood][this.chordIdx % 4];
      this.chordIdx++;
      this.pad(chord.map((n) => ROOT + n), this.nextChord, chordLen + 1.5, mood === 'tense' ? 0.05 : 0.07);
      if (this.drone) this.drone.osc.frequency.setTargetAtTime(mtof(ROOT - 12 + chord[0]), this.nextChord, 0.8);
      this.nextChord += chordLen;
    }
    if (t + 0.2 >= this.nextNote) {
      const step = mood === 'tense' ? 0.2 : mood === 'triumph' ? 0.32 : 0.55 + Math.random() * 0.9;
      if (mood === 'tense') {
        const n = SCALE[Math.floor(Math.random() * 5)] + ROOT + 12;
        this.bell(n, this.nextNote, 0.05, 0.6);
      } else if (Math.random() < (mood === 'triumph' ? 0.9 : 0.6)) {
        const n = SCALE[Math.floor(Math.random() * SCALE.length)] + ROOT + 12 + (Math.random() < 0.3 ? 12 : 0);
        this.bell(n, this.nextNote, mood === 'triumph' ? 0.09 : 0.065, mood === 'triumph' ? 2.5 : 3.5);
      }
      this.nextNote += step;
    }
    if (mood === 'tense' && t + 0.2 >= this.pulseNext) {
      this.kick(this.pulseNext, 0.5);
      this.pulseNext = Math.max(this.pulseNext + 0.4, t);
    }
  }

  private pad(notes: number[], when: number, dur: number, vol: number) {
    const ctx = this.ctx!;
    const gain = ctx.createGain();
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(500, when);
    filter.frequency.linearRampToValueAtTime(1400, when + dur * 0.5);
    filter.frequency.linearRampToValueAtTime(600, when + dur);
    filter.Q.value = 0.7;
    gain.gain.setValueAtTime(0, when);
    gain.gain.linearRampToValueAtTime(vol, when + dur * 0.35);
    gain.gain.linearRampToValueAtTime(0, when + dur);
    filter.connect(gain).connect(this.music);
    const oscs: OscillatorNode[] = [];
    for (const n of notes) {
      for (const det of [-7, 6]) {
        const o = ctx.createOscillator();
        o.type = 'sawtooth';
        o.frequency.value = mtof(n);
        o.detune.value = det;
        const og = ctx.createGain();
        og.gain.value = 0.25;
        o.connect(og).connect(filter);
        o.start(when);
        o.stop(when + dur + 0.1);
        oscs.push(o);
      }
    }
    this.padVoices.push({ osc: oscs, gain, filter });
    if (this.padVoices.length > 6) this.padVoices.shift();
  }

  private bell(note: number, when: number, vol: number, decay: number) {
    const ctx = this.ctx!;
    const f = mtof(note);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, when);
    g.gain.linearRampToValueAtTime(vol, when + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, when + decay);
    g.connect(this.music);
    for (const [mult, amp] of [[1, 1], [2.01, 0.35], [3.02, 0.12]] as const) {
      const o = ctx.createOscillator();
      o.type = 'sine';
      o.frequency.value = f * mult;
      const og = ctx.createGain();
      og.gain.value = amp;
      o.connect(og).connect(g);
      o.start(when);
      o.stop(when + decay + 0.05);
    }
  }

  private kick(when: number, vol: number) {
    const ctx = this.ctx!;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.frequency.setValueAtTime(110, when);
    o.frequency.exponentialRampToValueAtTime(38, when + 0.25);
    g.gain.setValueAtTime(vol, when);
    g.gain.exponentialRampToValueAtTime(0.001, when + 0.4);
    o.connect(g).connect(this.music);
    o.start(when);
    o.stop(when + 0.45);
  }

  // ------------------------------------------------------------------ sound effects
  /** Play a recorded effect if it is loaded; returns false so the caller can synthesise instead. */
  private playSample(id: string, vol: number, pitch: number, pan: number, when: number) {
    const s = this.samples.get(id);
    if (!s) return false;
    const ctx = this.ctx!;
    const src = ctx.createBufferSource();
    src.buffer = s.buf;
    src.playbackRate.value = pitch;
    const g = ctx.createGain();
    g.gain.value = vol * s.norm;
    const p = ctx.createStereoPanner();
    p.pan.value = pan;
    src.connect(g).connect(p).connect(this.sfxBus);
    src.start(when);
    return true;
  }

  private noise(when: number, dur: number, vol: number, type: BiquadFilterType, f0: number, f1: number, q = 1, pan = 0) {
    const ctx = this.ctx!;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    const filt = ctx.createBiquadFilter();
    filt.type = type;
    filt.frequency.setValueAtTime(f0, when);
    filt.frequency.exponentialRampToValueAtTime(Math.max(20, f1), when + dur);
    filt.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, when);
    g.gain.linearRampToValueAtTime(vol, when + Math.min(0.02, dur * 0.2));
    g.gain.exponentialRampToValueAtTime(0.0008, when + dur);
    const p = ctx.createStereoPanner();
    p.pan.value = pan;
    src.connect(filt).connect(g).connect(p).connect(this.sfxBus);
    src.start(when, Math.random() * 1.5);
    src.stop(when + dur + 0.05);
  }
  private tone(when: number, dur: number, vol: number, f0: number, f1: number, type: OscillatorType = 'sine', pan = 0) {
    const ctx = this.ctx!;
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.setValueAtTime(f0, when);
    o.frequency.exponentialRampToValueAtTime(Math.max(20, f1), when + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, when);
    g.gain.linearRampToValueAtTime(vol, when + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0008, when + dur);
    const p = ctx.createStereoPanner();
    p.pan.value = pan;
    o.connect(g).connect(p).connect(this.sfxBus);
    o.start(when);
    o.stop(when + dur + 0.05);
  }

  /** Which recording a game sound plays, with its level and pitch (null: synthesised only). */
  private resolve(name: string, opts: { volume?: number; pitch?: number; form?: string }) {
    const v = opts.volume ?? 1;
    const pt = opts.pitch ?? 1;
    const fc = FORM_CUES[name];
    if (fc) return { id: fc.prefix + (FORMS.includes(opts.form ?? '') ? opts.form : 'clay'), vol: fc.vol * v, rate: pt * (1 + (Math.random() * 2 - 1) * fc.vary) };
    if (name === 'dash')
      return opts.form === 'stone' ? { id: 'sfx_charge', vol: 0.8 * v, rate: pt } : { id: 'sfx_dash', vol: 0.55 * v, rate: pt * (1 + (Math.random() - 0.5) * 0.1) };
    const cue = CUES[name];
    if (!cue) return null;
    return { id: cue.ids[Math.floor(Math.random() * cue.ids.length)], vol: cue.vol * v, rate: pt * (1 + (Math.random() * 2 - 1) * (cue.vary ?? 0)) };
  }

  play(name: string, opts: { volume?: number; pitch?: number; pan?: number; form?: string } = {}) {
    if (this.hushed) return;
    const pan = Math.max(-1, Math.min(1, opts.pan ?? 0));
    if (this.recorder) {
      const r = this.resolve(name, opts);
      if (r) this.recorder.sfx(r.id, r.vol, r.rate, pan);
      return;
    }
    const ctx = this.ctx;
    if (!ctx || this.muted) return;
    const t = ctx.currentTime + 0.005;
    const r = this.resolve(name, opts);
    if (r && this.playSample(r.id, r.vol, r.rate, pan, t)) return;
    this.synth(name, t, opts.volume ?? 1, opts.pitch ?? 1, pan, opts.form);
  }

  /** The original procedural effects: the fallback when a recording is unavailable. */
  private synth(name: string, t: number, v: number, pt: number, pan: number, form?: string) {
    switch (name) {
      case 'jump':
        this.noise(t, 0.18, 0.18 * v, 'bandpass', 900 * pt, 2600 * pt, 1.2, pan);
        this.tone(t, 0.12, 0.05 * v, 300 * pt, 520 * pt, 'triangle', pan);
        break;
      case 'flip':
        this.noise(t, 0.28, 0.16 * v, 'bandpass', 600, 3500, 2, pan);
        this.tone(t, 0.2, 0.06 * v, 520, 900, 'sine', pan);
        break;
      case 'land':
        this.noise(t, 0.12, 0.25 * v, 'lowpass', 900 * pt, 200, 1, pan);
        this.tone(t, 0.1, 0.12 * v, 140 * pt, 60, 'sine', pan);
        break;
      case 'hardLand':
      case 'poundImpact':
      case 'colossusStep':
        this.noise(t, 0.5, 0.5 * v, 'lowpass', 1200, 80, 0.8, pan);
        this.tone(t, 0.45, 0.45 * v, 90, 30, 'sine', pan);
        break;
      case 'step': {
        const f = form === 'stone' ? 0.5 : form === 'glass' ? 2.2 : form === 'wood' ? 1.3 : 1;
        this.noise(t, 0.06, 0.07 * v, 'bandpass', 1400 * f, 600 * f, 2, pan);
        if (form === 'glass') this.tone(t, 0.08, 0.03 * v, 2400 + Math.random() * 600, 2000, 'sine', pan);
        break;
      }
      case 'dash':
      case 'pound':
        this.noise(t, 0.3, 0.25 * v, 'bandpass', 2400, 500, 0.9, pan);
        break;
      case 'walljump':
        this.noise(t, 0.15, 0.18 * v, 'bandpass', 1500, 3000, 1.5, pan);
        break;
      case 'climb':
        this.noise(t, 0.2, 0.1 * v, 'bandpass', 800, 1600, 1, pan);
        break;
      case 'transform': {
        const base = form === 'stone' ? 220 : form === 'wood' ? 330 : form === 'glass' ? 660 : 440;
        [0, 4, 7, 12].forEach((s, i) => this.tone(t + i * 0.035, 0.7, 0.07 * v, base * Math.pow(2, s / 12), base * Math.pow(2, s / 12) * 1.01, 'sine', pan));
        this.noise(t, 0.5, 0.12 * v, 'highpass', 3000, 8000, 0.7, pan);
        break;
      }
      case 'imprint':
      case 'absorb':
        [0, 7, 12, 19].forEach((s, i) => this.tone(t + i * 0.05, 0.9, 0.06 * v, 440 * Math.pow(2, s / 12), 440 * Math.pow(2, s / 12), 'sine', pan));
        break;
      case 'crumble':
        this.noise(t, 1.2, 0.6 * v, 'lowpass', 1800, 90, 0.6, pan);
        this.tone(t, 0.8, 0.4 * v, 70, 28, 'sine', pan);
        for (let i = 0; i < 6; i++) this.noise(t + 0.1 + Math.random() * 0.6, 0.12, 0.15 * v, 'bandpass', 2500, 900, 3, pan);
        break;
      case 'splash':
        this.noise(t, 0.6, 0.35 * v, 'bandpass', 2400, 400, 0.8, pan);
        break;
      case 'checkpoint':
        [0, 7, 12, 16].forEach((s, i) => this.tone(t + i * 0.08, 1.4, 0.06 * v, mtof(ROOT + 24 + s), mtof(ROOT + 24 + s), 'sine', pan));
        break;
      case 'plateDown':
        this.tone(t, 0.25, 0.2 * v, 160, 90, 'triangle', pan);
        this.noise(t, 0.2, 0.15 * v, 'lowpass', 700, 200, 1, pan);
        break;
      case 'plateUp':
        this.tone(t, 0.2, 0.1 * v, 120, 180, 'triangle', pan);
        break;
      case 'gate':
        this.noise(t, 1.4, 0.3 * v, 'lowpass', 500, 120, 1, pan);
        this.tone(t, 1.2, 0.12 * v, 55, 48, 'sawtooth', pan);
        break;
      case 'thud':
        this.tone(t, 0.3, 0.3 * v, 100, 40, 'sine', pan);
        break;
      case 'melt':
        this.noise(t, 0.9, 0.3 * v, 'bandpass', 600, 150, 3, pan);
        this.tone(t, 0.8, 0.12 * v, 300, 80, 'sine', pan);
        break;
      case 'burn':
        this.noise(t, 0.9, 0.35 * v, 'highpass', 1500, 400, 0.5, pan);
        break;
      case 'shatter':
        this.noise(t, 0.6, 0.45 * v, 'highpass', 4000, 9000, 0.7, pan);
        for (let i = 0; i < 8; i++) this.tone(t + Math.random() * 0.3, 0.3, 0.04 * v, 2000 + Math.random() * 3000, 1800 + Math.random() * 2000, 'sine', pan);
        break;
      case 'respawn':
        [12, 7, 0].forEach((s, i) => this.tone(t + i * 0.07, 0.6, 0.06 * v, mtof(ROOT + 24 + s), mtof(ROOT + 24 + s), 'sine', pan));
        break;
      case 'rumble':
        this.noise(t, 3, 0.5 * v, 'lowpass', 300, 60, 0.7, pan);
        this.tone(t, 3, 0.25 * v, 42, 30, 'sine', pan);
        break;
      case 'slam':
      case 'roar':
        this.noise(t, 1.6, 0.8 * v, 'lowpass', 900, 50, 0.6, pan);
        this.tone(t, 1.2, 0.6 * v, 60, 24, 'sine', pan);
        break;
      case 'awaken':
      case 'restore':
      case 'sting':
      case 'titleBoom':
        [0, 7, 12, 19, 24].forEach((s, i) => this.tone(t + i * 0.18, 3, 0.05 * v, mtof(ROOT + 12 + s), mtof(ROOT + 12 + s), 'sine', pan));
        break;
      case 'ui':
      case 'uiMove':
      case 'uiBack':
        this.tone(t, 0.12, 0.05 * v, 880, 1320, 'sine', pan);
        break;
      // creature vocals have no synthesised stand-in
    }
  }
}
